import{_ as l,l as i,o as e,c as o,v as r,p as s,x as t,d,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"场外与经销商市场","description":"","frontmatter":{"title":"场外与经销商市场","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/otc-dealer-market.md","filePath":"quant/otc-dealer-market.md","lastUpdated":1789023840000}'),h={name:"quant/otc-dealer-market.md"};function u(c,a,B,m,f,_){const n=i("Mermaid");return e(),o("div",null,[a[1]||(a[1]=r('<h1 id="场外与经销商市场" tabindex="-1">场外与经销商市场 <a class="header-anchor" href="#场外与经销商市场" aria-label="Permalink to &quot;场外与经销商市场&quot;">​</a></h1><div class="epigraph"><p>拍卖市场把未成交意向写成公共簿；经销商市场把流动性写成对特定客户、特定数量、特定时刻的承诺。价格可以打印出来，却不必对你可执行。</p><footer>—— Duffie, Gârleanu and Pedersen, Over-the-Counter Markets, Econometrica, 2005；对照 Harris, Trading and Exchanges 对经销商与拍卖的对照</footer></div><p><a href="/quant/pre-post-market">盘前盘后</a> 是连续竞价变薄之后的弱经销商形态：人少、价差宽、关系开始重要。缺口是完整的场外（OTC）经销商市场——公司债、许多衍生品、部分外汇与股票第三市场——默认就没有一张对全市场有效的 <a href="/quant/lob-structure">LOB</a>。Duffie、Gârleanu 与 Pedersen 把 OTC 写成搜索与议价：找到对手要时间，议价力决定加价。本课写协议差别，不把债券 TRACE 度量再推一遍，也不把宏观利率决定写成微观结构。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>公开限价簿回答三个问题：立刻成交的价格、更深处的量、新单插在哪。经销商市场把三个问题都变成私有。客户向一家或几家经销商询价，收到的是对<em>该客户</em>有效的双向或单向报价，深度通常只覆盖所询数量，时间优先没有公共队列。成交之后，监管磁带可能打印一个价格，其他客户不能点击。流动性状态是网络宽度、经销商库存、以及你被识别成什么类型的流——与<a href="/quant/retail-wholesaler">批发商筛选零售</a> 同构，只是这里几乎没有公开簿可对照。</p><p>问题是：在搜索成本与存货风险下，为何拍卖没有完全取代经销商；以及透明度（事后打印）如何改变议价，却不必产生事前 BBO。</p><h3 id="拍卖与经销商不是道德标签" tabindex="-1">拍卖与经销商不是道德标签 <a class="header-anchor" href="#拍卖与经销商不是道德标签" aria-label="Permalink to &quot;拍卖与经销商不是道德标签&quot;">​</a></h3><p>Harris 把两种结构当成设计选择。同质、连续、小额的流适合集中竞价；异质契约、大额、违约跳跃昂贵的资产，集中簿的逆向选择与空簿成本可以高于关系型存货。公司债条款各异、持有人分散，经销商用资本连接非同步的买卖。股票之所以能以 LOB 为主，是因为合约同质、噪声流厚。把 OTC 写成「落后」，会漏掉：对象资产可能根本撑不起一张公共簿。</p><p><span class="marginnote">场外不等于非法。美国公司债 OTC 是主市场；股票场外打印可以是合法内化。对象是匹配协议，不是监管形容词。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>度量从「BBO 价差」改成：搜索时间、回复率、成交相对基准的偏离、经销商买卖加价（若能识别方向）、以及给定数量下的变现时间。Duffie–Gârleanu–Pedersen 的比较静态：搜寻摩擦下降（电子化、集中名单）则加价下降、成交更快；风险上升则经销商要求更宽或拒绝。经验上必须分层：小额电子、大额语音、冷门与热门券不能合成一个价差。</p><p>不要把 <a href="/quant/kyle-model">Kyle</a> 的公开 \\(y\\) 套到 OTC：做市商看见的不是匿名净流，而是<em>谁</em>在询、询多大。价格歧视是机制，不是噪声。全国 \\(\\lambda\\) 在此没有对象，除非先定义「可观测的总流」——债券里往往没有。</p>',12)),(e(),s(E,null,{default:t(()=>[p(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20LR%0A%20%20Buy%5B%22%E4%B9%B0%E6%96%B9%E6%90%9C%E7%B4%A2%22%5D%20--%3E%20D%5B%22%E7%BB%8F%E9%94%80%E5%95%86%E5%AD%98%E8%B4%A7%20%2F%20%E5%8C%B9%E9%85%8D%22%5D%0A%20%20Sell%5B%22%E5%8D%96%E6%96%B9%E6%90%9C%E7%B4%A2%22%5D%20--%3E%20D%0A%20%20D%20--%3E%20Print%5B%22%E4%BA%8B%E5%90%8E%E7%A3%81%E5%B8%A6%3A%20%E4%B8%8D%E5%8F%AF%E7%82%B9%E5%87%BB%22%5D%0A%20%20Search%5B%22%E6%90%9C%E5%AF%BB%E6%91%A9%E6%93%A6%22%5D%20--%3E%20Markup%5B%22%E8%AE%AE%E4%BB%B7%E5%8A%A0%E4%BB%B7%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>经销商同时卖搜索和存货。搜索：你不必等到自然对手出现。存货：对手暂时不存在时，经销商先扛着，再在网络里卸掉。加价补偿双向搜索成本、库存风险、以及逆向选择（你可能比他更知情）。事后透明（TRACE 一类）削弱「别人成交在哪」的信息租金，加价可以下降，但存货功能仍在——Edwards–Harris–Piwowar 的方向是透明度，不是把债券变成股票。事前若强制公开可点击的厚簿，知情流可能把做市商撤出，市场退回更少的关系交易。</p><p>对执行：可成交价是一次询价的结果。用昨日打印当今日限价，忽略搜索与歧视。评级事件日回复消失，是流动性状态跳变，不是数据缺失。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>股票第三市场、公司债、互换、外汇都叫 OTC，搜寻技术与监管磁带差一个数量级，系数不能共用。中央清算改变的是对手方风险，不自动产生公共簿。下一课把询价收成可标准化的电子协议：RFQ 平台——仍是经销商市场，只是搜索被做成报文。</p><p><span class="marginnote">指示性屏幕报价不是 BBO。把屏幕中点当 NBBO 去做有效价差，是把 OTC 错写成股票。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>经销商市场用搜索与存货替代公共队列；打印价格对非当事客户通常不可执行。</li><li>资产同质性与噪声厚度决定拍卖能否取代关系型做市。</li><li>事后透明可压缩信息租金，不必创造事前全国簿。</li><li>核心–边缘网络里，危机首先是核心资本与授信收缩，而不是公开深度消失。</li><li>出处：Duffie, Gârleanu and Pedersen, <em>Econometrica</em>, 2005；Harris, <em>Trading and Exchanges</em>；透明度经验见 Edwards, Harris and Piwowar, <em>Journal of Finance</em>, 2007。</li></ul>',8))])}const q=l(h,[["render",u]]);export{T as __pageData,q as default};
